from fastapi import FastAPI
from graphene import ObjectType, Int, String, List, Schema, Field, Mutation
from fastapi_gql import GQL

posts_data = []
next_id = 1

class Post(ObjectType):
    id = Int()
    title = String()

class CreatePost(Mutation):
    class Arguments:
        title = String(required=True)
    Output = Post

    def mutate(self, info, title):
        global next_id
        post = {'id': next_id, 'title': title}
        posts_data.append(post)
        next_id += 1
        return Post(**post)

class Query(ObjectType):
    posts = List(Post)

    def resolve_posts(self, info):
        return [Post(**p) for p in posts_data]

schema = Schema(query=Query, mutation=CreatePost)
app = FastAPI()
GQL(app, schema=schema)

